<!--
 * 灰度实验管理页面
 *
 * <p>消息通道灰度发布实验管理，支持创建实验、编辑、查看分桶分配、停止实验等操作。
 *
 * @path apps/message-web/src/views/canary/index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 灰度实验管理（列表页）
 * <p>消费后端契约 CanaryController（src/api/canary.ts，auto-generated by bash/gen-contract.py）：
 * createExperiment() 创建灰度实验，assignBucket() 查询分桶分配结果。
 * 顶部快速创建表单，列表展示实验及其操作。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page, useYDSZModal } from '@ydsz/common-ui';

import { createLogger } from '@YDSZ-core/shared/utils';
import {
  ElButton,
  ElDialog,
  ElForm,
  ElFormItem,
  ElInput,
  ElInputNumber,
  ElMessage,
  ElMessageBox,
  ElOption,
  ElSelect,
  ElTable,
  ElTableColumn,
  ElTag,
} from 'element-plus';
import { h, onMounted, reactive, ref } from 'vue';

import { assignBucket, createExperiment } from '#/api/canary';

defineOptions({ name: 'CanaryManagement' });

const logger = createLogger('canary-management');

/** 实验列表数据（灰度实验暂无 list 接口，前端维护已创建记录） */
const experimentList = ref<CanaryExperimentRow[]>([]);

/** 加载状态 */
const loading = ref(false);

/** 快速创建表单 — 实验名称 */
const quickForm = reactive({
  experimentName: '',
  templateCode: '',
  channel: '',
  canaryPercent: 10,
  metricsGoal: '',
});

/** 快速创建表单可见性 */
const quickCreateVisible = ref(false);

/** 分桶分配结果弹窗可见性 */
const bucketVisible = ref(false);

/** 当前查询的实验 ID */
const bucketExperimentId = ref('');

/** 当前查询的请求键 */
const bucketRequestKey = ref('');

/** 分桶分配结果 */
const bucketResult = ref('');

/** 查询分桶表单 */
const bucketForm = reactive({
  experimentId: '',
  requestKey: '',
});

/** 实验状态标签类型 */
function getStatusType(status?: string): 'success' | 'danger' | 'warning' | 'info' {
  const upper = (status ?? '').toUpperCase();
  if (upper === 'RUNNING' || upper === 'ACTIVE') return 'success';
  if (upper === 'STOPPED' || upper === 'TERMINATED') return 'danger';
  if (upper === 'DRAFT') return 'warning';
  return 'info';
}

/** 实验状态标签文本 */
function getStatusLabel(status?: string): string {
  const labels: Record<string, string> = {
    RUNNING: '运行中',
    ACTIVE: '运行中',
    STOPPED: '已停止',
    TERMINATED: '已停止',
    DRAFT: '草稿',
  };
  return labels[(status ?? '').toUpperCase()] ?? status ?? '-';
}

/** 灰度实验行数据结构 */
interface CanaryExperimentRow {
  id: string;
  name: string;
  channel: string;
  status: string;
  trafficPercentage: number;
  createdAt: string;
}

/** 加载实验列表（前端本地维护，实际项目中可扩展为分页接口） */
function loadExperiments(): void {
  loading.value = true;
  // 合约当前仅有 createExperiment 和 assignBucket 两个端点，无列表接口；
  // 实验记录由前端本地维护（创建后追加）。预留扩展点：后续接入 listExperiment 接口。
  loading.value = false;
}

/** 快速创建实验 */
async function handleQuickCreate(): Promise<void> {
  if (!quickForm.experimentName.trim()) {
    ElMessage.warning('请输入实验名称');
    return;
  }
  if (!quickForm.channel.trim()) {
    ElMessage.warning('请选择通道');
    return;
  }
  try {
    const experimentId = await createExperiment({
      experimentName: quickForm.experimentName.trim(),
      templateCode: quickForm.templateCode.trim() || undefined,
      channel: quickForm.channel.trim(),
      canaryPercent: quickForm.canaryPercent,
      metricsGoal: quickForm.metricsGoal.trim() || undefined,
    });
    // 添加到本地列表
    const newExperiment: CanaryExperimentRow = {
      id: experimentId ?? `exp-${Date.now()}`,
      name: quickForm.experimentName.trim(),
      channel: quickForm.channel.trim(),
      status: 'RUNNING',
      trafficPercentage: quickForm.canaryPercent,
      createdAt: new Date().toISOString().replace('T', ' ').slice(0, 19),
    };
    experimentList.value.unshift(newExperiment);
    ElMessage.success('创建实验成功');
    quickCreateVisible.value = false;
    resetQuickForm();
  } catch (error) {
    logger.warn('创建灰度实验失败: {}', error);
    // 错误提示由 errorMessageResponseInterceptor 统一处理
  }
}

/** 重置快速创建表单 */
function resetQuickForm(): void {
  quickForm.experimentName = '';
  quickForm.templateCode = '';
  quickForm.channel = '';
  quickForm.canaryPercent = 10;
  quickForm.metricsGoal = '';
}

/** 查看分桶分配 */
async function handleViewBucket(row: CanaryExperimentRow): Promise<void> {
  bucketForm.experimentId = row.id;
  bucketForm.requestKey = '';
  bucketResult.value = '';
  bucketVisible.value = true;
}

/** 执行分桶查询 */
async function handleAssignBucket(): Promise<void> {
  if (!bucketForm.experimentId.trim()) {
    ElMessage.warning('请输入实验ID');
    return;
  }
  if (!bucketForm.requestKey.trim()) {
    ElMessage.warning('请输入请求键');
    return;
  }
  try {
    const result = await assignBucket({
      experimentId: bucketForm.experimentId.trim(),
      requestKey: bucketForm.requestKey.trim(),
    });
    bucketResult.value = result ?? '-';
  } catch (error) {
    logger.warn('查询分桶分配失败: {}', error);
    // 错误提示由 errorMessageResponseInterceptor 统一处理
  }
}

/** 停止实验 */
async function handleStopExperiment(row: CanaryExperimentRow): Promise<void> {
  try {
    await ElMessageBox.confirm(
      `确定停止实验「${row.name}」吗？停止后灰度流量将切回主版本。`,
      '停止确认',
      { type: 'warning' },
    );
  } catch {
    logger.debug('用户取消停止实验操作');
    return;
  }
  // 合约暂无 stopExperiment 接口，前端本地更新状态
  const target = experimentList.value.find((item) => item.id === row.id);
  if (target) {
    target.status = 'STOPPED';
  }
  ElMessage.success('实验已停止');
}

/** 编辑实验 */
function handleEdit(row: CanaryExperimentRow): void {
  logger.info('编辑实验: id={}', row.id);
  // 合约暂无 updateExperiment 接口，预留扩展
  ElMessage.info('编辑功能待后端接口支持');
}

onMounted(() => {
  loadExperiments();
});
</script>

<template>
  <Page auto-content-height>
    <div class="canary-container p-4">
      <!-- 顶部快速创建 -->
      <ElCard class="mb-4" shadow="never">
        <div class="flex items-center justify-between">
          <h3 class="text-base font-medium">灰度实验管理</h3>
          <ElButton type="primary" @click="quickCreateVisible = true">
            创建实验
          </ElButton>
        </div>
      </ElCard>

      <!-- 实验列表 -->
      <ElCard shadow="never">
        <ElTable v-loading="loading" :data="experimentList" stripe border style="width: 100%">
          <ElTableColumn type="index" label="序号" width="60" align="center" />
          <ElTableColumn prop="name" label="实验名称" min-width="160" />
          <ElTableColumn prop="channel" label="通道" width="120">
            <template #default="{ row }">
              <ElTag size="small">{{ row.channel }}</ElTag>
            </template>
          </ElTableColumn>
          <ElTableColumn label="状态" width="100" align="center">
            <template #default="{ row }">
              <ElTag :type="getStatusType(row.status)" size="small">
                {{ getStatusLabel(row.status) }}
              </ElTag>
            </template>
          </ElTableColumn>
          <ElTableColumn label="灰度流量" width="120" align="center">
            <template #default="{ row }">
              <span class="font-mono text-blue-600">{{ row.trafficPercentage }}%</span>
            </template>
          </ElTableColumn>
          <ElTableColumn prop="createdAt" label="创建时间" width="180" />
          <ElTableColumn label="操作" width="260" fixed="right" align="center">
            <template #default="{ row }">
              <ElButton size="small" link type="primary" @click="handleEdit(row)">
                编辑
              </ElButton>
              <ElButton size="small" link type="primary" @click="handleViewBucket(row)">
                查看分配
              </ElButton>
              <ElButton
                size="small"
                link
                type="danger"
                :disabled="row.status === 'STOPPED'"
                @click="handleStopExperiment(row)"
              >
                停止
              </ElButton>
            </template>
          </ElTableColumn>
        </ElTable>

        <!-- 空状态提示 -->
        <div
          v-if="experimentList.length === 0 && !loading"
          class="py-12 text-center text-gray-400"
        >
          暂无灰度实验，点击右上角「创建实验」按钮开始
        </div>
      </ElCard>

      <!-- 快速创建弹窗 -->
      <ElDialog
        v-model="quickCreateVisible"
        title="创建灰度实验"
        width="520px"
        :close-on-click-modal="false"
      >
        <ElForm :model="quickForm" label-width="100px">
          <ElFormItem label="实验名称" required>
            <ElInput
              v-model="quickForm.experimentName"
              placeholder="请输入实验名称"
              clearable
            />
          </ElFormItem>
          <ElFormItem label="模板编码">
            <ElInput
              v-model="quickForm.templateCode"
              placeholder="关联模板编码（可选）"
              clearable
            />
          </ElFormItem>
          <ElFormItem label="通道" required>
            <ElSelect v-model="quickForm.channel" placeholder="请选择通道" class="w-full">
              <ElOption label="邮件" value="EMAIL" />
              <ElOption label="短信" value="SMS" />
              <ElOption label="站内信" value="INBOX" />
              <ElOption label="Webhook" value="WEBHOOK" />
            </ElSelect>
          </ElFormItem>
          <ElFormItem label="灰度比例">
            <ElInputNumber
              v-model="quickForm.canaryPercent"
              :min="1"
              :max="100"
              :step="5"
              class="w-full"
            />
            <span class="ml-2 text-gray-400">%</span>
          </ElFormItem>
          <ElFormItem label="目标指标">
            <ElInput
              v-model="quickForm.metricsGoal"
              placeholder="灰度实验目标指标（可选）"
              type="textarea"
              :rows="2"
              clearable
            />
          </ElFormItem>
        </ElForm>
        <template #footer>
          <ElButton @click="quickCreateVisible = false">取消</ElButton>
          <ElButton type="primary" @click="handleQuickCreate">确认创建</ElButton>
        </template>
      </ElDialog>

      <!-- 分桶分配查询弹窗 -->
      <ElDialog v-model="bucketVisible" title="灰度分桶分配查询" width="520px">
        <ElForm :model="bucketForm" label-width="100px">
          <ElFormItem label="实验ID">
            <ElInput v-model="bucketForm.experimentId" placeholder="实验ID" clearable />
          </ElFormItem>
          <ElFormItem label="请求键">
            <ElInput v-model="bucketForm.requestKey" placeholder="请求键（用户ID等）" clearable />
          </ElFormItem>
        </ElForm>
        <div v-if="bucketResult" class="mt-4 rounded bg-gray-50 p-3">
          <span class="text-sm text-gray-500">分配结果：</span>
          <span class="ml-2 font-mono font-bold text-blue-600">{{ bucketResult }}</span>
        </div>
        <template #footer>
          <ElButton @click="bucketVisible = false">关闭</ElButton>
          <ElButton type="primary" @click="handleAssignBucket">查询</ElButton>
        </template>
      </ElDialog>
    </div>
  </Page>
</template>
